<?php
require "../include/bittorrent.php";
dbconn(); loggedinorreturn();
require_once __DIR__ . '/../include/medal_fragments.php';
medal_fragment_ensure_tables();
$uid=(int)$CURUSER['id']; $message='';

function exchange_part_amount(int $uid,int $medalId,int $part):int { $r=sql_query("SELECT amount FROM medal_fragment_parts WHERE uid={$uid} AND medal_id={$medalId} AND part_no={$part} LIMIT 1"); $x=$r?mysql_fetch_assoc($r):null; return (int)($x['amount']??0); }
function exchange_part_credit(int $uid,int $medalId,int $part,int $amount):void { $now=date('Y-m-d H:i:s'); sql_query("INSERT INTO medal_fragment_parts(uid,medal_id,part_no,amount,created_at,updated_at) VALUES({$uid},{$medalId},{$part},{$amount},'{$now}','{$now}') ON DUPLICATE KEY UPDATE amount=amount+{$amount},updated_at='{$now}'"); }

$medals=[]; $r=sql_query("SELECT m.id,m.name FROM medals m INNER JOIN medal_fragment_config c ON c.medal_id=m.id AND c.enabled=1 WHERE m.display_on_medal_page=1 ORDER BY m.priority DESC,m.id DESC"); while($r&&($x=mysql_fetch_assoc($r)))$medals[]=$x;
$medalNames=[]; foreach($medals as $m)$medalNames[(int)$m['id']]=$m['name'];
$myMissing=[]; $myOwned=[]; foreach($medals as $m){$parts=medal_fragment_part_totals($uid,(int)$m['id']);foreach($parts as $part=>$amount){$key=(int)$m['id'].':'.(int)$part;if($amount>0)$myOwned[$key]=true;else $myMissing[$key]=['medal_id'=>(int)$m['id'],'part_no'=>(int)$part,'label'=>$m['name'].' · 部位 '.$part];}}

if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='offer'){
  $offerKey=explode(':',(string)($_POST['offer_key']??''));$offerMedal=(int)($offerKey[0]??0);$offerPart=(int)($offerKey[1]??0);$wantKey=(string)($_POST['want_key']??'');$want=explode(':',$wantKey);$wantMedal=(int)($want[0]??0);$wantPart=(int)($want[1]??0);$amount=max(1,(int)($_POST['amount']??1));
  if(!isset($myOwned[$offerMedal.':'.$offerPart]))$message='你没有可供交易的该部位碎片。';
  elseif(!isset($myMissing[$wantMedal.':'.$wantPart]))$message='只能选择自己缺少的碎片。';
  elseif(exchange_part_amount($uid,$offerMedal,$offerPart)<$amount)$message='该部位碎片数量不足。';
  else {sql_query("UPDATE medal_fragment_parts SET amount=amount-{$amount},updated_at=NOW() WHERE uid={$uid} AND medal_id={$offerMedal} AND part_no={$offerPart} AND amount>={$amount}");if(mysql_affected_rows()!==1)$message='锁定碎片失败，请重试。';else{sql_query("INSERT INTO medal_fragment_trades_v2(seller_uid,offer_medal_id,offer_part_no,offer_amount,want_medal_id,want_part_no,want_amount,created_at) VALUES({$uid},{$offerMedal},{$offerPart},{$amount},{$wantMedal},{$wantPart},{$amount},NOW())");$message='交易已上架，系统会自动限制重复拥有的部位参与交易。';}}
 }
 if($action==='accept'){
  $id=(int)$_POST['id'];$t=mysql_fetch_assoc(sql_query("SELECT * FROM medal_fragment_trades_v2 WHERE id={$id} AND status='open' LIMIT 1"));
  if(!$t||$t['seller_uid']===$uid)$message='交易不存在，或不能接受自己的交易。';
  elseif(exchange_part_amount($uid,(int)$t['offer_medal_id'],(int)$t['offer_part_no'])>0)$message='你已经拥有对方提供的部位，不能重复参与本次交易。';
  elseif(exchange_part_amount($uid,(int)$t['want_medal_id'],(int)$t['want_part_no'])<(int)$t['want_amount'])$message='你缺少对方需要的部位，无法完成交易。';
  else{sql_query("UPDATE medal_fragment_parts SET amount=amount-".(int)$t['want_amount'].",updated_at=NOW() WHERE uid={$uid} AND medal_id=".(int)$t['want_medal_id']." AND part_no=".(int)$t['want_part_no']." AND amount>=".(int)$t['want_amount']);if(mysql_affected_rows()!==1)$message='扣除交易碎片失败。';else{exchange_part_credit($uid,(int)$t['offer_medal_id'],(int)$t['offer_part_no'],(int)$t['offer_amount']);exchange_part_credit((int)$t['seller_uid'],(int)$t['want_medal_id'],(int)$t['want_part_no'],(int)$t['want_amount']);sql_query("UPDATE medal_fragment_trades_v2 SET buyer_uid={$uid},status='done',completed_at=NOW() WHERE id={$id} AND status='open'");$message='交易完成，碎片已到账。';}}
 }
}

$trades=[];$r=sql_query("SELECT t.*,u.username FROM medal_fragment_trades_v2 t LEFT JOIN users u ON u.id=t.seller_uid WHERE t.status='open' ORDER BY t.id DESC LIMIT 100");while($r&&($x=mysql_fetch_assoc($r)))$trades[]=$x;
stdhead('勋章碎片交易所');begin_main_frame();echo '<style>
.nova-exchange{max-width:1160px;margin:18px auto 34px;color:#28464d}.nova-exchange-hero{padding:24px 28px;border-radius:12px;background:linear-gradient(115deg,#103d49,#087d75);color:#fff;box-shadow:0 13px 28px rgba(15,75,79,.18)}.nova-exchange h1{margin:0 0 7px!important;color:#fff!important;font-size:25px!important}.nova-exchange h1:after{display:none!important}.nova-exchange-hero p{margin:0;color:rgba(255,255,255,.78);line-height:1.7;font-size:13px}.nova-exchange-panel{margin-top:16px;padding:18px 20px;border:1px solid #d8e8e8;border-radius:10px;background:#fff;box-shadow:0 6px 18px rgba(35,76,82,.06)}.nova-exchange-panel h2{margin:0 0 13px!important;color:#173f49!important;font-size:18px!important}.nova-exchange-panel h2:after{display:none!important}.nova-exchange-form{display:grid;grid-template-columns:1fr 1fr 120px auto;gap:9px;align-items:end}.nova-exchange-form label{display:block;color:#688187;font-size:11px}.nova-exchange-form select,.nova-exchange-form input{width:100%;height:36px;box-sizing:border-box;border:1px solid #cbdfe0;border-radius:6px;padding:0 9px;background:#fbfefe}.nova-exchange button{height:36px;padding:0 15px;border:0;border-radius:6px;background:#0c9a88;color:#fff;font-weight:800;cursor:pointer}.nova-exchange button:hover{background:#087b70}.nova-exchange-notice{margin:12px 0;padding:10px 12px;border-radius:6px;background:#eef9f6;color:#0b7c70;font-size:12px}.nova-trade-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.nova-trade-card{position:relative;padding:16px;border:1px solid #d8e8e8;border-radius:9px;background:linear-gradient(145deg,#fff,#f5fbfa);box-shadow:0 5px 14px rgba(35,76,82,.05)}.nova-trade-card h3{margin:0 0 11px;color:#26474f;font-size:14px}.nova-trade-card .trade-arrow{display:flex;align-items:center;justify-content:center;gap:8px;margin:9px 0;color:#0a9181;font-weight:800}.nova-trade-card .trade-chip{display:inline-block;padding:7px 9px;border-radius:5px;background:#e8f7f3;color:#0b746b;font-size:12px;font-weight:750}.nova-trade-card .trade-meta{margin:10px 0;color:#71868a;font-size:11px}.nova-trade-card form{text-align:right}.nova-empty{padding:24px;text-align:center;color:#778b8e}.nova-part-option{display:none}@media(max-width:850px){.nova-trade-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.nova-exchange-form{grid-template-columns:1fr 1fr}}@media(max-width:560px){.nova-trade-grid{grid-template-columns:1fr}.nova-exchange-form{grid-template-columns:1fr}.nova-exchange-panel{padding:14px 12px}}
</style><div class="nova-exchange"><div class="nova-exchange-hero"><h1>勋章碎片交易所</h1><p>挂牌你多余的部位，系统只允许交换你尚未拥有的部位；接受交易时会再次校验双方库存，避免重复获得同一部位。</p></div>';
if($message!=='')echo '<div class="nova-exchange-notice">'.htmlspecialchars($message).'</div>';
echo '<section class="nova-exchange-panel"><h2>发布交易</h2><form class="nova-exchange-form" method="post"><input type="hidden" name="action" value="offer"><label>我提供的部位<select name="offer_key" id="offer_key">';foreach($myOwned as $key=>$v){[$mid,$part]=array_map('intval',explode(':',$key));echo '<option value="'.$key.'">'.htmlspecialchars($medalNames[$mid]).' · 部位 '.$part.'</option>';}$firstMissing=array_key_first($myMissing);echo '</select></label><label>我需要的部位<select name="want_key">';foreach($myMissing as $key=>$v)echo '<option value="'.$key.'">'.htmlspecialchars($v['label']).'</option>';echo '</select></label><label>交换数量<input type="number" name="amount" min="1" value="1"></label><button type="submit">上架等量交易</button></form><p style="margin:10px 0 0;color:#7b8d90;font-size:11px">可叠加相同部位碎片。已拥有的部位不会出现在“我需要”的选项中。</p></section>';
echo '<section class="nova-exchange-panel"><h2>公开交易展示区</h2><div class="nova-trade-grid">';foreach($trades as $t){$offer=htmlspecialchars($medalNames[(int)$t['offer_medal_id']].' · 部位 '.(int)$t['offer_part_no']);$want=htmlspecialchars($medalNames[(int)$t['want_medal_id']].' · 部位 '.(int)$t['want_part_no']);echo '<article class="nova-trade-card"><h3>'.htmlspecialchars($t['username']??'用户').' 的交易</h3><div class="trade-arrow"><span class="trade-chip">提供 '.$offer.' × '.(int)$t['offer_amount'].'</span><b>⇄</b><span class="trade-chip">需要 '.$want.' × '.(int)$t['want_amount'].'</span></div><div class="trade-meta">只有缺少“提供部位”且拥有“需要部位”的用户可以参与</div><form method="post"><input type="hidden" name="action" value="accept"><input type="hidden" name="id" value="'.(int)$t['id'].'"><button type="submit">立即交换</button></form></article>';}if(!$trades)echo '<div class="nova-empty">当前暂无公开交易，发布你的多余碎片来寻找需要的部位。</div>';echo '</div></section></div>';end_main_frame();stdfoot();
